content.content:
  .cell { background: var(--bg); }
  .panel { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
  .box { background: var(--panel); border-radius: 6px; padding: 10px 14px; }
  .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); }
  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
  .preview { display: flex; flex-direction: column; gap: 10px; margin-top: 6px; }
  .preview-item {
    display: grid;
    grid-template-columns: repeat(4, 18px);
    grid-template-rows: repeat(2, 18px);
    gap: 1px;
  }
  .preview-item div { background: transparent; }
  .help { font-size: 13px; color: var(--muted); }
  .help b { color: var(--text); font-weight: 600; }
  button {
    font: inherit;
  }

  function cleanQueue(queue) {
    if (!Array.isArray(queue)) return [];
    return queue
      .map(function (p) { return String(p).toUpperCase(); })
      .filter(function (p) { return TYPES.indexOf(p) !== -1; });
  }

  var PREVIEW_COUNT = 3;

  // Keep enough upcoming pieces to fill the preview.
  function fillUpcoming() {
    while (upcoming.length < PREVIEW_COUNT) upcoming.push(randomPiece());
  }

  function pieceCells(p, rot, row, col) {
    return ROTATIONS[p.type][rot].map(function (o) { return [row + o[0], col + o[1]]; });
  }

  function fits(p, rot, row, col) {
    var cells = pieceCells(p, rot, row, col);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
      if (board[r][c]) return false;
    }
    return true;
  }

  function spawn() {
    fillUpcoming();
    var type = upcoming.shift();
    fillUpcoming();
    var p = { type: type, rot: 0, row: SPAWN[type][0], col: SPAWN[type][1], lockTicks: 0, lockResets: 0 };
    if (!fits(p, p.rot, p.row, p.col)) {
  var levelEl = document.getElementById("level");
  var linesEl = document.getElementById("lines");
  var previewEl = document.getElementById("preview");
  var cellEls = [];
  var previewItems = []; // { el, cells: [8 divs] }, soonest first

  (function buildDom() {
    for (var r = 0; r < ROWS; r++) {
      cellEls.push([]);
      for (var c = 0; c < COLS; c++) {
        var el = document.createElement("div");
        el.className = "cell";
        el.setAttribute("data-testid", "cell");
        el.setAttribute("data-row", String(r));
        el.setAttribute("data-col", String(c));
        el.setAttribute("data-filled", "false");
        el.setAttribute("data-piece", "");
        boardEl.insertBefore(el, overlayEl);
        cellEls[r].push(el);
      }
    }
    for (var i = 0; i < PREVIEW_COUNT; i++) {
      var item = document.createElement("div");
      item.className = "preview-item";
      item.setAttribute("data-testid", "next-piece-item");
      var cells = [];
      for (var k = 0; k < 8; k++) {
        var cell = document.createElement("div");
        item.appendChild(cell);
        cells.push(cell);
      }
      previewEl.appendChild(item);
      previewItems.push({ el: item, cells: cells });
    }
  })();

  function paint(el, type) {
    var cls = el.className.replace(/\s*p-[IOTSZJL]\b/g, "");
    el.className = type ? cls + " p-" + type : cls;
  }

  function render() {
    var drawn = board.map(function (row) { return row.slice(); });
    if (current) {
      pieceCells(current, current.rot, current.row, current.col).forEach(function (rc) {
        drawn[rc[0]][rc[1]] = current.type;
      });
    }
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) {
        var el = cellEls[r][c];
        var type = drawn[r][c] || "";
        if (el.getAttribute("data-piece") === type) continue;
        el.setAttribute("data-piece", type);
        el.setAttribute("data-filled", type ? "true" : "false");
        paint(el, type);
      }
    }

    scoreEl.textContent = String(score);
    levelEl.textContent = String(level);
    linesEl.textContent = String(lines);

    previewItems.forEach(function (item, i) {
      var nextType = upcoming[i] || "";
      item.el.setAttribute("data-piece", nextType);
      item.el.hidden = !nextType;
      item.cells.forEach(function (el) { paint(el, ""); });
      if (!nextType) return;
      // Use the spawn orientation, trimmed to its occupied rows.
      var cells = ROTATIONS[nextType][0];
      var minRow = Math.min.apply(null, cells.map(function (o) { return o[0]; }));
      cells.forEach(function (o) {
        var el = item.cells[(o[0] - minRow) * 4 + o[1]];
        if (el) paint(el, nextType);
      });
    });

    overlayEl.hidden = status !== "gameover";
  }

  // ---- Test control surface ----
  window.__tetris = {
    newGame: function (queue) {
      newGame(queue);
      render();
    },
    setQueue: function (queue) {
      upcoming = cleanQueue(queue);
      fillUpcoming();
      render();
    },
    setBoard: function (rows) {
      var b = emptyBoard();
      for (var r = 0; r < ROWS; r++) {
        var line = rows && rows[r] != null ? String(rows[r]) : "";
        for (var c = 0; c < COLS; c++) {
          var ch = line.charAt(c);
          b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
        }
      }
      board = b;
      render();
    },
    tick: function (n) {
      var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
      for (var i = 0; i < steps; i++) gravityStep();
      render();
    },
    input: function (action) {
      performAction(action);
      render();
    },
    getBoard: function () {
      return board.map(function (row) {
        return row.map(function (cell) { return cell || "."; }).join("");
      });
    },
    getState: function () {
      return {
        current: current
          ? { type: current.type, cells: pieceCells(current, current.rot, current.row, current.col) }
          : null,
        next: upcoming.slice(),
        score: score,
        level: level,
        lines: lines,
        status: status
      };
    }
  };
